$('copy').onclick=async()=>{const t=items.filter(needs).map(x=>`${x.name} — ${fmt(amount(x))} ${x.unit}`).join('\n');try{await navigator.clipboard.writeText(t);message('Список скопирован.');}catch{message('Не удалось скопировать список.');}};
function checkFields(){return {checkedAt:serverTimestamp(),checkedBy:user.email||'Пользователь'};}
function validPhoto(v){return typeof v==='string'&&v.startsWith('data:image/jpeg;base64,')&&v.length<=65000;}
function showPhoto(){const ok=validPhoto(photoDraft);$('photoArea').hidden=!ok;if(ok)$('photoPreview').src=photoDraft;else $('photoPreview').removeAttribute('src');$('save').disabled=photoBusy;}
$('photoRemove').onclick=()=>{photoToken++;photoBusy=false;photoDraft=null;$('photoFile').value='';showPhoto();};
$('photoFile').onchange=async()=>{const f=$('photoFile').files[0];if(!f)return;const token=++photoToken;photoBusy=true;showPhoto();$('editMsg').textContent='Сжимаем фото…';let url;try{if(f.size>20*1024*1024)throw Error('Выберите изображение до 20 МБ.');url=URL.createObjectURL(f);const img=new Image();img.src=url;await img.decode();let result;for(const size of [320,240,160]){const canvas=document.createElement('canvas'),ratio=Math.min(1,size/Math.max(img.width,img.height));canvas.width=Math.max(1,Math.round(img.width*ratio));canvas.height=Math.max(1,Math.round(img.height*ratio));const ctx=canvas.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);result=canvas.toDataURL('image/jpeg',.65);if(validPhoto(result))break;}if(!validPhoto(result))throw Error('Не удалось сжать изображение.');if(token===photoToken){photoDraft=result;$('editMsg').textContent='Фото готово к сохранению.';}}catch(e){if(token===photoToken)$('editMsg').textContent='Не удалось открыть фото. Попробуйте JPG или PNG.';}finally{if(url)URL.revokeObjectURL(url);if(token===photoToken){photoBusy=false;showPhoto();}}};
$('toggleGroups').onclick=()=>{if(visibleGroups.every(c=>expanded.has(c)))visibleGroups.forEach(c=>expanded.delete(c));else visibleGroups.forEach(c=>expanded.add(c));render();};
$('inventoryStart').onclick=()=>startInventory(visibleStock);
function startInventory(rows){if(!ready||!rows.length)return;inventoryIds=rows.map(x=>x.id);inventoryIndex=0;inventoryChecked=0;inventoryBusy=false;$('inventoryDialog').showModal();inventoryLock(false);showInventory();}
function showInventory(){while(inventoryIndex<inventoryIds.length&&!items.some(x=>x.id===inventoryIds[inventoryIndex]&&x.active!==false))inventoryIndex++;if(inventoryIndex>=inventoryIds.length){$('inventoryDialog').close();message(`Проверка завершена. Сохранено: ${inventoryChecked} из ${inventoryIds.length}.`);return;}inventoryBase=items.find(x=>x.id===inventoryIds[inventoryIndex]);const x=inventoryBase;$('inventoryName').textContent=x.name;$('inventoryInfo').textContent=`${x.category} · Норма ${fmt(x.norm)} ${x.unit} · минимум ${fmt(x.min)}`;$('inventoryProgress').textContent=`${inventoryIndex+1} из ${inventoryIds.length} · проверено ${inventoryChecked}`;$('inventoryBar').max=inventoryIds.length;$('inventoryBar').value=inventoryIndex;$('inventoryQty').value=x.qty??'';$('inventoryMsg').textContent='';}
function inventoryLock(v){inventoryBusy=v;for(const id of ['inventorySave','inventorySkip','inventoryHide','inventoryZero','inventoryNorm','inventoryClose'])$(id).disabled=v;$('inventoryQty').disabled=v;}
async function saveInventory(hide=false){if(inventoryBusy||!ready||!inventoryBase)return;const base=inventoryBase;const n=Number($('inventoryQty').value);if(!hide&&($('inventoryQty').value===''||!Number.isFinite(n)||n<0)){$('inventoryMsg').textContent='Укажите фактический остаток.';return;}inventoryLock(true);try{await runTransaction(db,async tx=>{const ref=doc(itemsRef,base.id),snap=await tx.get(ref);if(!snap.exists())throw Error('Товар был удалён. Пропустите его.');const x=snap.data();if(x.qty!==base.qty||x.active!==base.active||x.unit!==base.unit)throw Error('Товар изменён на другом устройстве. Пропустите и откройте заново.');tx.update(ref,hide?{active:false,updatedAt:serverTimestamp()}:{qty:round(n),...checkFields(),updatedAt:serverTimestamp()});log(tx,hide?'Скрытие':'Проверка',x,hide?'Не используем':`${fmt(x.qty)} → ${fmt(round(n))} ${x.unit}`);});inventoryChecked++;inventoryIndex++;showInventory();}catch(e){$('inventoryMsg').textContent=err(e);}finally{inventoryLock(false);}}
$('inventoryForm').onsubmit=e=>{e.preventDefault();saveInventory();};$('inventoryZero').onclick=()=>$('inventoryQty').value=0;$('inventoryNorm').onclick=()=>$('inventoryQty').value=inventoryBase.norm;$('inventorySkip').onclick=()=>{if(!inventoryBusy){inventoryIndex++;showInventory();}};$('inventoryHide').onclick=()=>saveInventory(true);$('inventoryClose').onclick=()=>$('inventoryDialog').close();$('inventoryDialog').addEventListener('cancel',e=>{if(inventoryBusy)e.preventDefault();});
